  if (a === null) {
    let b: Wrap | null = Wrap$fromJson("{\"data\":42}");
    if (b === null) {
      let c: Wrap | null = Wrap$fromJson("{\"data\":\"x\"}");
      if (c === null) {
        let d: Wrap | null = Wrap$fromJson("{\"data\":null}");
        if (d === null) { return 1; }
        return 0;
      }
      return 0;
    }
