// @jsonable
export class Point {
  x: int = 0;
}
// @jsonable
export class Wrap {
  data: table = {};
}
export function test(): string {
  let p: Point = { x: 1 };
  let w: Wrap = { data: { p: p } };
  return Wrap$toJson(w);
}

// @jsonable
export class Child {
  value: int = 0;
}
// @jsonable
export class MaybeChild {
  child?: Child | null;
}
export function test(): string {
  let n: MaybeChild | null = MaybeChild$fromJson("{\"child\":null}");
  if (n !== null) {
    if (!has(n.child)) { return "no-has-null"; }
    if (n.child !== null) { return "not-null"; }
  } else {
    return "n-null";
  }
  let v: MaybeChild | null = MaybeChild$fromJson("{\"child\":{\"value\":8}}");
  if (v !== null) {
    if (!has(v.child)) { return "no-child"; }
    let child: Child | null = v.child;
    if (child !== null) {
      if (child.value !== 8) { return "bad"; }
    } else {
      return "child-null";
    }
    let v2: MaybeChild | null = MaybeChild$fromJson(MaybeChild$toJson(v));
    if (v2 !== null) {
      let c2: Child | null = v2.child;
      if (c2 !== null) {
        if (c2.value !== 8) { return "bad2"; }
      } else {
        return "c2-null";
      }
    } else {
      return "v2-null";
    }
  } else {
    return "v-null";
  }
  let m: MaybeChild | null = MaybeChild$fromJson("{}");
  if (m !== null) {
    if (has(m.child)) { return "has-missing"; }
  } else {
    return "m-null";
  }
  return "ok";
}

// @jsonable
export class Wrap {
  data: table = {};
}
export function test(): string {
  let s: string = "{\"data\":";
  let i: int = 0;
  while (i < 600) { s = s + "{\"k\":"; i = i + 1; }
  s = s + "{\"k\":[1]}";
  i = 0;
  while (i < 600) { s = s + "}"; i = i + 1; }
  s = s + "}";
  let w: Wrap | null = Wrap$fromJson(s);
  if (w !== null) { return "not-null"; }
  return "ok";
}

