}
// @jsonable
export class Wrap {
  data: table = {};
}
export function test(): string {
  let hi: User | null = User$fromJson("{\"name\":\"\uD800\"}");
  if (hi !== null) { return "hi-accepted"; }
  let lo: User | null = User$fromJson("{\"name\":\"\uDC00\"}");
  if (lo !== null) { return "lo-accepted"; }
  let leaf: Wrap | null = Wrap$fromJson("{\"data\":{\"leaf\":\"\uD800\"}}");
  if (leaf !== null) { return "leaf-accepted"; }
  return "ok";
}

// @jsonable
export class P {
  age: int = 0;
  score: number = 0.0;
}
// @jsonable
export class Wrap {
  data: table = {};
}
export function test(): string {
  let a: P | null = P$fromJson("{\"age\":01}");
  if (a !== null) { return "01"; }
  let b: P | null = P$fromJson("{\"age\":-01}");
  if (b !== null) { return "-01"; }
  let c: P | null = P$fromJson("{\"score\":1.}");
  if (c !== null) { return "1."; }
  let d: P | null = P$fromJson("{\"score\":1.e2}");
  if (d !== null) { return "1.e2"; }
  let e: P | null = P$fromJson("{\"score\":-.5}");
  if (e !== null) { return "-.5"; }
  let t: Wrap | null = Wrap$fromJson("{\"data\":{\"n\":01}}");
  if (t !== null) { return "table-01"; }
  let t2: Wrap | null = Wrap$fromJson("{\"data\":{\"n\":-01}}");
  if (t2 !== null) { return "table--01"; }
  let t3: Wrap | null = Wrap$fromJson("{\"data\":{\"n\":1.}}");
  if (t3 !== null) { return "table-1."; }
  let t4: Wrap | null = Wrap$fromJson("{\"data\":{\"n\":1.e2}}");
  if (t4 !== null) { return "table-1.e2"; }
  let t5: Wrap | null = Wrap$fromJson("{\"data\":{\"n\":-.5}}");
  if (t5 !== null) { return "table--.5"; }
  let ok: P | null = P$fromJson("{\"age\":42,\"score\":2.5}");
  if (ok !== null) {
    if (ok.age !== 42) { return "age"; }
    if (ok.score !== 2.5) { return "score"; }
  } else {
    return "ok-null";
  }
  let v: Wrap | null = Wrap$fromJson("{\"data\":{\"n\":10}}");
  if (v === null) { return "table-10-null"; }
  return "ok";
}

// @jsonable
export class Raw {
  i: int;
  n: number;
  b: boolean;
  s: string;
  data: table;
  xs: int[];
}
export function test(): string {
  let w: Raw | null = Raw$fromJson("{}");
  if (w !== null) {
    if (w.i !== 0) { return "i"; }
    if (w.n !== 0.0) { return "n"; }
    if (w.b !== false) { return "b"; }
    if (w.s !== "") { return "s"; }
    let j: string = Raw$toJson(w);
    if (j !== "{\"i\":0,\"n\":0.0,\"b\":false,\"s\":\"\",\"data\":{},\"xs\":[]}") { return "j:" + j; }
    let t: table = w.data;
    let miss: string | null = t.missing;
    if (miss !== null) { return "miss"; }
    if (w.xs.length !== 0) { return "len"; }
    let n0: int | null = w.xs[0];
    if (n0 !== null) { return "n0"; }
    w.xs[w.xs.length] = 7;
    let w2: Raw | null = Raw$fromJson("{}");
    if (w2 !== null) {
      if (w2.xs.length !== 0) { return "shared"; }
      let j2: string = Raw$toJson(w2);
      if (j2 !== j) { return "j2"; }
    } else {
      return "w2-null";
    }
    return "ok";
  }
  return "w-null";
}

// @jsonable
export class Child {
  x: int = 1;
}
// @jsonable
export class Holder {
  c: Child;
  i: int;
}
export function test(): string {
  let h: Holder | null = Holder$fromJson("{}");
  if (h !== null) { return "h-not-null"; }
  let h2: Holder | null = Holder$fromJson("{\"c\":{\"x\":9}}");
  if (h2 !== null) {
    if (h2.c.x !== 9) { return "x"; }
    if (h2.i !== 0) { return "i"; }
    let j: string = Holder$toJson(h2);
    if (j !== "{\"c\":{\"x\":9},\"i\":0}") { return "j:" + j; }
    return "ok";
  }
  return "h2-null";
}

// @jsonable
export class C {
  x: int = 0;
}
export function test(): string {
  if (C$fromJson("42") !== null) { return "s42"; }
  if (C$fromJson("\"x\"") !== null) { return "sstr"; }
  if (C$fromJson("true") !== null) { return "strue"; }
  if (C$fromJson("null") !== null) { return "snull"; }
  if (C$fromJson("[1,2]") !== null) { return "sarr"; }
  let from_obj: C | null = C$fromJson("{}");
  let from_arr: C | null = C$fromJson("[]");
  if (from_obj !== null) {
    if (from_arr !== null) {
      if (C$toJson(from_obj) !== C$toJson(from_arr)) { return "collapse-neq"; }
    } else {
      return "arr-null";
    }
  } else {
    return "obj-null";
  }
  return "ok";
}

// @jsonable
export class Matrix {
  values: int[][] = [];
}
// @jsonable
export class Cube {
  values: int[][][] = [];
}
export function test(): string {
  let m: Matrix = { values: [[1, 2], [3, 4]] };
  let json: string = Matrix$toJson(m);
  let m2: Matrix | null = Matrix$fromJson(json);
  if (m2 !== null) {
    if (m2.values[0][0] !== 1 || m2.values[1][1] !== 4) { return "m-bad"; }
  } else {
    return "m-null";
  }
  let c: Cube = { values: [[[1, 2], [3, 4]], [[5, 6], [7, 8]]] };
  let cjson: string = Cube$toJson(c);
  let c2: Cube | null = Cube$fromJson(cjson);
  if (c2 !== null) {
    if (c2.values[0][0][0] !== 1 || c2.values[1][1][1] !== 8) { return "c-bad"; }
  } else {
    return "c-null";
  }
  return "ok";
}

// @jsonable
export class Wrap {
  data: table = {};
}
export function test(): string {
  let w: Wrap = { data: { values: [[1, 2], [3, 4]] } };
  let json: string = Wrap$toJson(w);
  let w2: Wrap | null = Wrap$fromJson(json);
  if (w2 !== null) {
    let json2: string = Wrap$toJson(w2);
    let w3: Wrap | null = Wrap$fromJson(json2);
    if (w3 !== null) {
      let t: table = w3.data;
      let values: int[][] = t.values;
      if (values[0][0] !== 1 || values[1][1] !== 4) { return "bad-values"; }
    } else {
      return "w3-null";
    }
  } else {
    return "w2-null";
  }
  return "ok";
}

