  let bad: Rec | null = Rec$fromJson("{\"a\":\"x\"}");
  if (bad !== null) { return "bad-not-null"; }
  let good: Rec | null = Rec$fromJson("{\"a\":7}");
  if (good !== null) {
    if (good.a !== 7) { return "a"; }
    if (good.b !== 1) { return "b"; }
